css:
& { padding:0; gap:0; overflow:hidden; isolation:isolate; }
.st-photo { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:-3; }
.st-shade { position:absolute; inset:0; z-index:-2; background:linear-gradient(90deg,var(--bg),color-mix(in srgb,var(--bg) 90%,transparent) 28%,color-mix(in srgb,var(--bg) 20%,transparent) 74%),linear-gradient(0deg,color-mix(in srgb,var(--bg) 95%,transparent),transparent 70%); }
.st-head { position:absolute; left:100px; top:82px; width:1350px; }
.st-kicker { font:500 22px/1.3 var(--font-mono,var(--mono)); letter-spacing:.13em; text-transform:uppercase; color:var(--accent); }
.st-head h2 { font-family:var(--font-display,var(--font)); font-size:76px; line-height:1.06; max-width:27ch; margin:22px 0 0; text-wrap:balance; }
.st-head p:empty,.st-head h2:empty { display:none; }
.st-intro { font-size:28px; color:var(--muted); line-height:1.4; max-width:53ch; margin-top:24px!important; }
.st-items { list-style:none; padding:0; margin:0; }
.st-items li { opacity:1!important; transform:none!important; }
.st-items li b { display:block; font-weight:650; line-height:1.14; text-wrap:balance; overflow-wrap:anywhere; }
.st-items li span { display:block; line-height:1.4; overflow-wrap:anywhere; }
.st-endnote { position:absolute; left:100px; right:100px; bottom:95px; font-size:32px; line-height:1.3; color:var(--ink); opacity:0; transition:opacity .65s; max-width:58ch; }
&:has([data-template-end].in) .st-endnote,&:has([data-template-end]:not([data-step])) .st-endnote { opacity:1; }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&[data-body-motion="none"] * { transition:none!important; }
@media (prefers-reduced-motion:reduce) { & * { transition:none!important; animation:none!important; } }
.st-intro { display:none; }.st-shade { background:color-mix(in srgb,var(--bg) 92%,transparent); }
.tf-paths { position:absolute; inset:0; width:1920px; height:1080px; overflow:visible; fill:var(--accent); }
.tf-route { fill:none; stroke:var(--line); stroke-width:3; stroke-linecap:round; transition:stroke .7s,stroke-width .7s; }
.tf-b { stroke-dasharray:.012 .009; }.tf-start { position:absolute; left:100px; top:675px; width:275px; font-size:27px; color:var(--muted); }
.tf-items { position:absolute; inset:0; }.tf-items li { position:absolute; width:495px; padding:26px 20px 24px 0; background:linear-gradient(90deg,var(--bg) 75%,transparent); }
.tf-items li::before { content:""; position:absolute; left:-7px; top:-8px; width:16px; height:16px; border-radius:50%; background:var(--line); transition:background .6s,box-shadow .6s; }
.tf-items li b { font-size:35px; color:var(--muted); transition:color .6s; }.tf-items li span { font-size:29px; margin-top:17px; color:var(--muted); opacity:0; transition:opacity .6s; }
.tf-items li:nth-child(1) { top:415px; left:620px; }.tf-items li:nth-child(2) { top:415px; left:1220px; }.tf-items li:nth-child(3) { top:745px; left:620px; }.tf-items li:nth-child(4) { top:745px; left:1220px; }
.tf-items li.in span { opacity:1; }.tf-items li.step-current b { color:var(--accent); }.tf-items li.step-current span { color:var(--ink); }.tf-items li.step-current::before { background:var(--accent); box-shadow:0 0 30px var(--accent); }
&:has(.tf-items li:nth-child(-n+2).step-current) .tf-a { stroke:var(--accent); stroke-width:5; }
&:has(.tf-items li:nth-child(n+3).step-current) .tf-b { stroke:var(--accent-2); stroke-width:5; }
.tf-items li:nth-child(n+3).step-current b { color:var(--accent-2); }.tf-items li:nth-child(n+3).step-current::before { background:var(--accent-2); box-shadow:0 0 30px var(--accent-2); }
.st-endnote { bottom:55px; font-size:27px; }
&:has([data-template-end].in), &:has([data-template-end]:not([data-step])) { .tf-a { stroke:var(--accent); }.tf-b { stroke:var(--accent-2); }.tf-items li span { opacity:1; }.tf-items li b { color:var(--ink); }.tf-items li::before { background:var(--accent); }.tf-items li:nth-child(n+3)::before { background:var(--accent-2); } }
